definition.script:
import groovy.json.JsonSlurper;

pipeline {
    agent any
    stages {
        stage('Import data (fully compliant studies)') {
            steps {
                withAWS(role: 'dbgap-etl', roleAccount: '736265540791', duration: 3600, roleSessionName: 'subject-multi-pipeline') {
                    s3Download(file: 'Managed_Inputs.csv', bucket: 'avillach-73-bdcatalyst-etl', path: 'general/resources/Managed_Inputs.csv', force: true)
                }

                script {

                    def inputs = readCSV file: 'Managed_Inputs.csv', format: CSVFormat.DEFAULT.withHeader()
                    def importRuns = [:]
                    def inputCount = 0
                    inputs.each() {
                        if (
                                it['Data is ready to process'] == 'Yes' & it["Data Processed"] == 'No' & it["Has Multi"] == 'Yes'
                                        & (it['Study Type'].equalsIgnoreCase('topmed') || it['Study Type'].equalsIgnoreCase('parent') || it['Study Type'].equalsIgnoreCase('substudy') 
                                        || it['Study Type'].equalsIgnoreCase('compliant'))
                        ) {

                            def stdy_id = it["Study Identifier"]
                            importRuns["importRuns${stdy_id}"] = {
                                build job: 'ETL - Pull Data from NHLBI S3',
                                        parameters: [
                                                string(name: 'study_abv_name', value: it['Study Abbreviated Name']),
                                                string(name: 'nhlbi_account_number', value: it['Pheno Ingest NHLBI Account']),
                                                string(name: 'bucket_s3_names', value: it['Pheno Ingest buckets'])
                                        ]
                            }

                        }
                    }
                    parallel importRuns
                }
            }
        }

        stage('Clean Metadata Directories') {
            steps {
                script {
                    build job: 'ETL - Clear Metadata Directories'
                }
            }
        }

        stage('Refreshing Curated Data Dictionaries') {
            steps {
                script {
                    build job: 'ETL - Import DBGAP Dictionaries to s3'
                }
            }
        }

        stage('Curate Data Dictionaries (fully compliant studies)') {
            steps {
                withAWS(role: 'dbgap-etl', roleAccount: '736265540791', duration: 3600, roleSessionName: 'subject-multi-pipeline') {
                    s3Download(file: 'Managed_Inputs.csv', bucket: 'avillach-73-bdcatalyst-etl', path: 'general/resources/Managed_Inputs.csv', force: true)
                }

                script {
                    def inputs = readCSV file: 'Managed_Inputs.csv', format: CSVFormat.DEFAULT.withHeader()
                    def metaRuns = [:]
                    def inputCount = 0
                    inputs.each() {
                       if (
                                it['Data is ready to process'] == 'Yes' & it["Data Processed"] == 'No' & it["Has Multi"] == 'Yes'
                                        & (it['Study Type'].equalsIgnoreCase('topmed') || it['Study Type'].equalsIgnoreCase('parent') || it['Study Type'].equalsIgnoreCase('substudy') 
                                        || it['Study Type'].equalsIgnoreCase('compliant'))
                        ) {
                            def stdy_id = it["Study Identifier"]
                            metaRuns["metaRuns${stdy_id}"] = {
                                build job: 'Curation - Compliant Data Dictionary to Metadata',
                                        parameters: [
                                                string(name: 'study_abv', value: it['Study Abbreviated Name']),
                                                string(name: 'study_id', value: it['Study Identifier'])
                                        ]
                            }
                        }
                    }
                    parallel metaRuns
                }
            }
        }

        stage('Import Metadata') {
            steps{
                script {
                    build job: 'ETL - Import Metadata From git'
                }
                withAWS(role: 'dbgap-etl', roleAccount: '736265540791', duration: 3600, roleSessionName: 'subject-multi-pipeline') {
                    s3Download(file: 'Managed_Inputs.csv', bucket: 'avillach-73-bdcatalyst-etl', path: 'general/resources/Managed_Inputs.csv', force: true)
                }
                script {

                    def inputs = readCSV file: 'Managed_Inputs.csv', format: CSVFormat.DEFAULT.withHeader()
                    def subjectRuns = [:]
                    def inputCount = 0
                    inputs.each() {
                       if (
                                it['Data is ready to process'] == 'Yes' & it["Data Processed"] == 'No' & it["Has Multi"] == 'Yes'
                                        & !(it['Subject Type(s)'].equalsIgnoreCase('multiple'))
                        ) {
                            def stdy_id = it["Study Identifier"]		   
                            subjectRuns["subjectRuns${stdy_id}"] = {
                                build job: 'ETL - Add Subject Type to Study Metadata',
                                        parameters: [
                                                string(name: 'study_abv', value: it['Study Abbreviated Name']),
                                                string(name: 'study_id', value: it['Study Identifier']),
                                                string(name: 'subject_type', value: it["Subject Type(s)"])
                                        ]
                            }
                        }
                    }
                    parallel subjectRuns
                }
            }
        }

        stage('Generate Missing Subject and Sample Files') {
            steps {
                withAWS(role: 'dbgap-etl', roleAccount: '736265540791', duration: 3600, roleSessionName: 'subject-multi-pipeline') {
                    s3Download(file: 'Managed_Inputs.csv', bucket: 'avillach-73-bdcatalyst-etl', path: 'general/resources/Managed_Inputs.csv', force: true)
                }

                script {
                    def inputs = readCSV file: 'Managed_Inputs.csv', format: CSVFormat.DEFAULT.withHeader()
                    def batchSize = 4
                    def jobs = []

                    inputs.each() {
                        if (it['Data is ready to process'] == 'Yes' && it["Data Processed"] == 'No') {
                            jobs << [
                                    stdy_id           : it["Study Identifier"],
                                    study_abbreviation: it['Study Abbreviated Name'],
                                    version           : it['Version'],
                                    phase             : it['Phase'],
                                    dmc_buckets       : it['Pheno Ingest buckets'],
                                    study_full_name   : it['Study Full Name']
                            ]
                        }
                    }

                    if (jobs) {
                        echo "Queued ${jobs.size()} study job(s) in batches of ${batchSize}"

                        jobs.collate(batchSize).eachWithIndex { batch, batchIndex ->
                            echo "Running batch ${batchIndex + 1} with ${batch.size()} job(s)"

                            def parallelJobs = [:]

                            batch.each { jobDef ->
                                def stdy_id = jobDef.stdy_id
                                def study_abbreviation = jobDef.study_abbreviation
                                def version = jobDef.version
                                def phase = jobDef.phase
                                def dmc_buckets = jobDef.dmc_buckets
                                def study_full_name = jobDef.study_full_name

                                parallelJobs["Create Sample and Subject Files - ${stdy_id}"] = {
                                    build job: 'Curation - Create Sample and Subject Files', parameters: [
                                            string(name: 'study_abbreviation', value: study_abbreviation),
                                            string(name: 'study_phs', value: stdy_id),
                                            string(name: 'version', value: version),
                                            string(name: 'phase', value: phase),
                                            string(name: 'dmc_buckets', value: dmc_buckets),
                                            string(name: 'study_full_name', value: study_full_name)
                                    ]
                                }
                            }

                            parallel parallelJobs + [failFast: true]
                        }
                    } else {
                        echo 'No studies ready to process.'
                    }
                }
            }
        }

        stage('Validate Duplicate Sample and Subject Multi Files Don\'t Exist') {
            steps {
                script {
                    build job: 'Validation Sample and Subject Multi Files'
                }
            }
        }

        stage('Decode Data') {
            steps {
                withAWS(role: 'dbgap-etl', roleAccount: '736265540791', duration: 3600, roleSessionName: 'subject-multi-pipeline') {
                    s3Download(file: 'Managed_Inputs.csv', bucket: 'avillach-73-bdcatalyst-etl', path: 'general/resources/Managed_Inputs.csv', force: true)
                }

                script {
                    def inputs = readCSV file: 'Managed_Inputs.csv', format: CSVFormat.DEFAULT.withHeader()
                    def decodeRuns = [:]
                    def inputCount = 0
                    inputs.each() {
                        if (it['Data is ready to process'] == 'Yes' & it["Data Processed"] == 'No' & it["Has Multi"] == 'Yes') {
                            def stdy_id = it["Study Identifier"]

                            if ((it['Study Identifier'] == 'phs000286' && it['Version'] == 'v7') ||
                                    (it['Study Identifier'] == 'phs000285' && it['Version'] == 'v3') ||
                                    (it['Study Identifier'] == 'phs000280' && it['Version'] == 'v8')) {
                                decodeRuns["decodeRuns${stdy_id}"] = {
                                    build job: 'Fix Column Alignment Issue',
                                            parameters: [
                                                    string(name: 'abv_name', value: it['Study Abbreviated Name']),
                                                    string(name: 'stdy_id', value: it['Study Identifier'])
                                            ]
                                }
                            } else {
                                decodeRuns["decodeRuns${stdy_id}"] = {
                                    build job: 'ETL - DBGap Decode Data',
                                            parameters: [
                                                    string(name: 'abv_name', value: it['Study Abbreviated Name']),
                                                    string(name: 'stdy_id', value: it['Study Identifier'])
                                            ]
                                }
                            }

                        }
                    }
                    parallel decodeRuns
                }
            }
        }

        stage('Sequence Patients') {
            steps {
                withAWS(role: 'dbgap-etl', roleAccount: '736265540791', duration: 3600, roleSessionName: 'semi-compliant-pipeline') {
                    s3Download(file: 'Managed_Inputs.csv', bucket: 'avillach-73-bdcatalyst-etl', path: 'general/resources/Managed_Inputs.csv', force: true)
                }

                script {
                    def inputs = readCSV file: 'Managed_Inputs.csv', format: CSVFormat.DEFAULT.withHeader()
                    def sequenceRuns = [:]
                    def hrmnCount = 0
                    inputs.each() {

                        if (it.get('Data is ready to process') == 'Yes' & it.get('Data Processed') == 'No' & it.get('Has Multi') == 'Yes') {
                            def stdy_id = it["Study Identifier"]
                            if (it.get('DCC Harmonized') == 'Yes') {
                                hrmnCount++;
                            }
                            sequenceRuns["sequenceRuns${stdy_id}"] = {
                                build job: 'ETL - DBGap Sequence Patients',
                                        parameters: [
                                                string(name: 'abv_name', value: it.get("Study Abbreviated Name"))
                                        ]
                            }
                        }
                    }
                    parallel sequenceRuns
                    if (hrmnCount > 0) {
                        echo 'Harmonized study/studies updated, refreshing DCC Harmonized with updated patient nums'
                        build job: 'ETL - Update DCC Harmonized'
                    }
                }
            }
        }
        stage('Generate Study Metadata') {
            steps {
                script {
                    build job: 'ETL - Generate Metadata'
                }
            }
        }
        stage('Generate Global Variables') {
            steps {
                script {
                    build job: '___ETL - Generate DBGAP Global Variables'
                }
                script {
                    build job: 'ETL - Generate DBGAP Global All Concepts'
                }
            }
        }
        stage('Create Mapping Files for Studies Not Processed Yet') {
            steps {

                script {
                    def mappingRuns = [:]
                    mappingRuns["noncomp-mapping"] = {
                        build job: 'ETL - Generate Non_DBGAP Mapping Files'
                    }
                    mappingRuns["comp-mapping"] = {
                        build job: 'ETL - Generate DBGAP Mapping Files'
                    }
                    parallel mappingRuns
                }
            }
        }

        stage('Generate All Concepts for Studies Not Processed Yet') {
            steps {
                script {
                    def allConceptsRuns = [:]
                    //def disabledRuns = [:]
                    allConceptsRuns["noncomp-allconcepts"] = {
                        build job: 'ETL - Generate Non-DBGap All Concepts with Data Type Analyzer'
                    }
                    allConceptsRuns["comp-allconcepts"] = {
                        build job: 'ETL - Generate DBGAP All Concepts with Data Type Analyzer'
                    }
                    parallel allConceptsRuns
                }
            }
        }


        stage('Generating Genomic Index Files Where Needed') {
            steps {
                script {
                    build job: 'ETL - Generate Genomic Index Files For Newly Ingested Studies'
                }
            }
        }
    }
}
